import { useEffect, useRef, useState, type ReactNode } from 'react';
import { useChatI18n } from '../utils/i18n';
import { SurfaceFocusBoundary } from './SurfaceFocusBoundary';
import { consume, emptyStream } from './stream';
import { bindingPath, isRecord, resolveValue, safeProperties, validAction } from './model';
import { setPointer } from './pointer';
import type { AgentCatalog } from './catalog';
import type { A2uiMessage, AgentComponent, AgentAction, AgentSurfaceError } from './protocol';

export interface AgentSurfaceProps {
  /** Immutable command log: append messages to update the rendered surfaces. */
  messages: A2uiMessage[];
  /** Trusted allow-list, created by the host rather than the agent. */
  catalog: AgentCatalog;
  onAction?: (action: AgentAction) => void;
  onError?: (error: AgentSurfaceError) => void;
}
export function AgentSurface({ messages, catalog, onError, onAction }: AgentSurfaceProps) {
  const { tc } = useChatI18n();
  const reported = useRef(new Set<string>());
  const errors: AgentSurfaceError[] = [];
  const [state, setState] = useState(emptyStream);
  if (state.messages !== messages) setState(consume(state, messages));
  errors.push(...state.errors);
  function renderNode(surfaceId: string, nodes: Map<string, AgentComponent>, id: string): ReactNode {
    const node = nodes.get(id);
    if (!node) return null;
    const entry = Object.hasOwn(catalog, node.component) ? catalog[node.component] : undefined;
    const surface = state.surfaces.get(surfaceId)!;
    let props: Record<string, unknown> | null = null;
    try {
      const input = safeProperties(node, surface.model);
      if (validAction(input.action)) props = entry?.validate(input) ?? null;
    } catch {
      /* Invalid paths and validators produce the same neutral placeholder. */
    }
    if (!entry || !props) {
      errors.push({ code: entry ? 'props' : 'component', surfaceId, componentId: id, type: node.component });
      return (
        <p key={id} className="text-muted-foreground">
          {tc('chat.surfaceUnsupported')}
        </p>
      );
    }
    const Component = entry.component;
    return (
      <Component
        key={id}
        props={props}
        onValueChange={(value) => {
          const path = bindingPath(node.value ?? node.checked);
          if (path === undefined) return;
          setState((current) => {
            const surface = current.surfaces.get(surfaceId);
            if (!surface) return current;
            const surfaces = new Map(current.surfaces);
            surfaces.set(surfaceId, { ...surface, model: setPointer(surface.model, path, value) });
            return { ...current, surfaces };
          });
        }}
        onAction={() => {
          if (!isRecord(node.action) || typeof node.action.name !== 'string') return;
          const context = resolveValue(node.action.context ?? {}, surface.model);
          if (isRecord(context)) onAction?.({ name: node.action.name, surfaceId, context });
        }}
      >
        {node.children?.map((child) => renderNode(surfaceId, nodes, child))}
      </Component>
    );
  }
  const content = [...state.surfaces].map(([id, surface]) => (
    <section
      key={id}
      data-agent-surface={id}
      aria-label={tc('chat.surfaceAgentContent')}
      className="rounded-lg border border-border bg-background p-3"
    >
      <p className="mb-3 text-xs font-semibold text-muted-foreground">{tc('chat.surfaceAgentContent')}</p>
      <form onSubmit={(event) => event.preventDefault()}>
        {surface.invalid ? (
          <p className="text-muted-foreground">{tc('chat.surfaceUnsupported')}</p>
        ) : (
          renderNode(id, surface.nodes, 'root')
        )}
      </form>
    </section>
  ));
  useEffect(() => {
    for (const error of errors) {
      const key = JSON.stringify(error);
      if (!reported.current.has(key)) {
        reported.current.add(key);
        onError?.(error);
      }
    }
  });
  return (
    <SurfaceFocusBoundary
      surfaceIds={new Set(state.surfaces.keys())}
      visible={state.surfaces.size > 0 || state.deleted}
      label={tc('chat.surfaceAgentContent')}
    >
      {content}
    </SurfaceFocusBoundary>
  );
}

import { Component, createRef, type ReactNode } from 'react';

const focusable = 'button, a[href], input, select, textarea, [tabindex], [contenteditable="true"]';
function candidates(element: Element): HTMLElement[] {
  return [element, ...element.querySelectorAll(focusable)].filter(
    (item): item is HTMLElement =>
      item instanceof HTMLElement &&
      item.matches(focusable) &&
      item.tabIndex >= 0 &&
      !item.matches(':disabled, [aria-disabled="true"], input[type="hidden"]') &&
      !item.closest('[hidden], [inert], [aria-hidden="true"]') &&
      getComputedStyle(item).display !== 'none' &&
      getComputedStyle(item).visibility !== 'hidden',
  );
}
interface Props {
  surfaceIds: ReadonlySet<string>;
  visible: boolean;
  label: string;
  children: ReactNode;
}
interface FocusSnapshot {
  siblings: Element[];
}

/** Capture focus before React removes DOM; restore after all deleted surfaces are gone. */
export class SurfaceFocusBoundary extends Component<Props> {
  private host = createRef<HTMLDivElement>();

  getSnapshotBeforeUpdate(): FocusSnapshot | null {
    const host = this.host.current;
    const active = document.activeElement;
    if (!host || !(active instanceof HTMLElement)) return null;
    let frame = host.contains(active) ? active.closest<HTMLElement>('[data-agent-surface]') : null;
    // Base UI Select options live in a portal. aria-controls identifies their owning trigger.
    if (!frame) {
      for (const trigger of host.querySelectorAll('[aria-controls]')) {
        const ownsFocus = (trigger.getAttribute('aria-controls') ?? '')
          .split(/\s+/)
          .some((id) => document.getElementById(id)?.contains(active));
        if (ownsFocus) {
          frame = trigger.closest<HTMLElement>('[data-agent-surface]');
          break;
        }
      }
    }
    if (!frame || this.props.surfaceIds.has(frame.dataset.agentSurface ?? '')) return null;
    const next: Element[] = [];
    // The next surface's controls, then the consumer's next focusable sibling.
    for (const start of [frame, host]) {
      let sibling = start.nextElementSibling;
      while (sibling) {
        next.push(sibling);
        sibling = sibling.nextElementSibling;
      }
    }
    return { siblings: next };
  }

  componentDidUpdate(_previous: Props, _state: unknown, snapshot: FocusSnapshot | null) {
    if (!snapshot) return;
    const restore = () => {
      // Resolve focusability after popup teardown has removed inert/aria-hidden markers.
      const next = snapshot.siblings.filter((element) => element.isConnected).flatMap(candidates);
      const composers = [...document.querySelectorAll('textarea')].flatMap(candidates);
      for (const target of [...next, ...composers, this.host.current]) {
        if (!target) continue;
        target.focus();
        if (document.activeElement === target) return;
      }
    };
    restore();
    queueMicrotask(() => {
      if (document.activeElement === document.body || document.activeElement === this.host.current) restore();
    });
  }

  render() {
    if (!this.props.visible) return null;
    return (
      <div
        ref={this.host}
        tabIndex={-1}
        role="group"
        aria-label={this.props.label}
        className="space-y-3 outline-focus-ring"
      >
        {this.props.children}
      </div>
    );
  }
}

import {
  Alert,
  Badge,
  Button,
  Card,
  Checkbox,
  Heading,
  Input,
  Link,
  SimpleSelect,
  Stack,
  Text,
  type HeadingLevel,
  type SpaceScale,
} from '@gntik-ai/ui';
import type { AgentCatalogRenderProps } from './catalog';
import { isRecord } from './model';

const text = (value: unknown) => (typeof value === 'string' ? value : '');

export function SurfaceText({ props }: AgentCatalogRenderProps) {
  return typeof props.href === 'string' && props.href ? (
    <Text>
      <Link href={props.href}>{text(props.text)}</Link>
    </Text>
  ) : (
    <Text>{text(props.text)}</Text>
  );
}
export function SurfaceHeading({ props }: AgentCatalogRenderProps) {
  return (
    <Heading level={typeof props.level === 'number' ? (props.level as HeadingLevel) : 2}>{text(props.text)}</Heading>
  );
}
export function SurfaceCard({ children }: AgentCatalogRenderProps) {
  return <Card className="space-y-3 p-4">{children}</Card>;
}
export function SurfaceStack({ props, children }: AgentCatalogRenderProps) {
  return (
    <Stack
      direction={props.direction === 'row' ? 'row' : 'column'}
      gap={typeof props.gap === 'number' ? (props.gap as SpaceScale) : 3}
    >
      {children}
    </Stack>
  );
}
export function SurfaceButton({ props, onAction }: AgentCatalogRenderProps) {
  return (
    <Button
      type="submit"
      className="motion-reduce:transition-none"
      disabled={props.disabled === true}
      onClick={onAction}
    >
      {text(props.label)}
    </Button>
  );
}
export function SurfaceInput({ props, onValueChange }: AgentCatalogRenderProps) {
  return (
    <label className="flex flex-col gap-2 text-sm text-foreground">
      {text(props.label)}
      <Input type="text" disabled={props.disabled === true} value={text(props.value)} onValueChange={onValueChange} />
    </label>
  );
}
export function SurfaceSelect({ props, onValueChange }: AgentCatalogRenderProps) {
  const items = Array.isArray(props.options)
    ? props.options.filter(isRecord).map((item) => ({ value: text(item.value), label: text(item.label) }))
    : [];
  return (
    <SimpleSelect<string>
      label={text(props.label)}
      disabled={props.disabled === true}
      value={typeof props.value === 'string' ? props.value : null}
      items={items}
      onValueChange={onValueChange}
    />
  );
}
export function SurfaceCheckbox({ props, onValueChange }: AgentCatalogRenderProps) {
  return (
    <Checkbox
      label={text(props.label)}
      disabled={props.disabled === true}
      checked={props.checked === true}
      onCheckedChange={onValueChange}
    />
  );
}
export function SurfaceAlert({ props }: AgentCatalogRenderProps) {
  return <Alert title={text(props.title)} description={text(props.text)} />;
}
export function SurfaceBadge({ props }: AgentCatalogRenderProps) {
  return <Badge>{text(props.text)}</Badge>;
}

import type { ComponentType, ReactNode } from 'react';
import {
  SurfaceAlert,
  SurfaceBadge,
  SurfaceButton,
  SurfaceCard,
  SurfaceCheckbox,
  SurfaceHeading,
  SurfaceInput,
  SurfaceSelect,
  SurfaceStack,
  SurfaceText,
} from './catalog-components';
import { isRecord } from './model';

/** Trusted host code: render explicit properties; never spread the agent's input. */
export interface AgentCatalogRenderProps {
  props: Readonly<Record<string, unknown>>;
  children?: ReactNode;
  onValueChange: (value: unknown) => void;
  onAction: () => void;
}
export interface AgentCatalogEntry {
  component: ComponentType<AgentCatalogRenderProps>;
  /** Return a fresh object of known properties, or null when invalid. */
  validate: (props: Readonly<Record<string, unknown>>) => Record<string, unknown> | null;
}
export type AgentCatalog = Readonly<Record<string, AgentCatalogEntry>>;
export function defineAgentCatalog(entries: AgentCatalog): AgentCatalog {
  return Object.freeze(
    Object.fromEntries(Object.entries(entries).map(([name, entry]) => [name, Object.freeze({ ...entry })])),
  );
}

type Rule = (value: unknown) => boolean;
const string: Rule = (value) => typeof value === 'string';
const label: Rule = (value) => typeof value === 'string' && value.trim().length > 0;
const optional =
  (rule: Rule): Rule =>
  (value) =>
    value === undefined || rule(value);
const boolean: Rule = (value) => typeof value === 'boolean';
function fields(rules: Record<string, Rule>): AgentCatalogEntry['validate'] {
  return (input) => {
    const output: Record<string, unknown> = {};
    for (const [key, rule] of Object.entries(rules)) {
      if (!rule(input[key])) return null;
      if (input[key] !== undefined) output[key] = input[key];
    }
    return output;
  };
}
const options: Rule = (value) =>
  Array.isArray(value) &&
  value.length <= 100 &&
  value.every((item) => isRecord(item) && label(item.value) && label(item.label)) &&
  new Set(value.map((item: unknown) => (isRecord(item) ? item.value : null))).size === value.length;

/** Small text/form catalog. Password, payment and file controls are deliberately absent. */
export const defaultAgentCatalog = defineAgentCatalog({
  Text: { component: SurfaceText, validate: fields({ text: string, href: optional(string) }) },
  Heading: {
    component: SurfaceHeading,
    validate: fields({
      text: label,
      level: optional((v) => typeof v === 'number' && Number.isInteger(v) && v >= 1 && v <= 6),
    }),
  },
  Card: { component: SurfaceCard, validate: fields({}) },
  Stack: {
    component: SurfaceStack,
    validate: fields({
      direction: optional((v) => v === 'row' || v === 'column'),
      gap: optional((v) => typeof v === 'number' && Number.isInteger(v) && v >= 0 && v <= 12),
    }),
  },
  Button: { component: SurfaceButton, validate: fields({ label, disabled: optional(boolean) }) },
  Input: {
    component: SurfaceInput,
    validate: fields({
      label,
      value: optional(string),
      disabled: optional(boolean),
      type: optional((v) => v === 'text'),
    }),
  },
  Select: {
    component: SurfaceSelect,
    validate: (input) => {
      const result = fields({
        label,
        value: optional((v) => v === null || typeof v === 'string'),
        options,
        disabled: optional(boolean),
      })(input);
      if (!result || !Array.isArray(result.options)) return null;
      return {
        ...result,
        options: result.options.filter(isRecord).map((item) => ({ value: item.value, label: item.label })),
      };
    },
  },
  Checkbox: {
    component: SurfaceCheckbox,
    validate: fields({ label, checked: optional(boolean), disabled: optional(boolean) }),
  },
  Alert: { component: SurfaceAlert, validate: fields({ title: label, text: optional(string) }) },
  Badge: { component: SurfaceBadge, validate: fields({ text: label }) },
});

export { AgentSurface, type AgentSurfaceProps } from './AgentSurface';
export {
  defineAgentCatalog,
  defaultAgentCatalog,
  type AgentCatalog,
  type AgentCatalogEntry,
  type AgentCatalogRenderProps,
} from './catalog';
export {
  A2UI_VERSION,
  type A2uiMessage,
  type AgentAction,
  type AgentComponent,
  type AgentSurfaceError,
} from './protocol';
export { doc as agentSurfaceDoc } from './AgentSurface.doc';

import { safeUrl } from '../markdown/Markdown';
import { getPointer } from './pointer';

export const isRecord = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value);

export function bindingPath(value: unknown): string | undefined {
  if (!isRecord(value) || !Object.hasOwn(value, 'path')) return undefined;
  if (typeof value.path !== 'string' || Object.keys(value).length !== 1) throw new Error('Invalid binding');
  // Validate even when the model has no value at this path yet.
  getPointer({}, value.path);
  return value.path;
}

export function resolveValue(value: unknown, model: unknown): unknown {
  const path = bindingPath(value);
  if (path !== undefined) return getPointer(model, path);
  if (Array.isArray(value)) return value.map((item) => resolveValue(item, model));
  if (isRecord(value))
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, resolveValue(item, model)]));
  return value;
}

/** Remove executable/structural properties before even a host validator sees agent input. */
export function safeProperties(input: Readonly<Record<string, unknown>>, model: unknown): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(input)) {
    if (
      /^on/i.test(key) ||
      [
        'id',
        'component',
        'children',
        'className',
        'style',
        'dangerouslySetInnerHTML',
        'ref',
        'key',
        'render',
        'as',
        '__proto__',
        'constructor',
        'prototype',
      ].includes(key)
    )
      continue;
    const resolved = resolveValue(value, model);
    result[key] =
      /(?:href|src|url)$/i.test(key) && typeof resolved === 'string' ? safeUrl(resolved) || undefined : resolved;
  }
  return result;
}

export function validAction(value: unknown): boolean {
  return (
    value === undefined ||
    (isRecord(value) &&
      typeof value.name === 'string' &&
      value.name.trim().length > 0 &&
      value.name.length <= 128 &&
      (value.context === undefined || isRecord(value.context)))
  );
}

/** RFC 6901 paths. Throws on malformed paths rather than guessing a model key. */
function segments(path: string): string[] {
  if (path === '') return [];
  if (!path.startsWith('/') || /~(?![01])/u.test(path)) throw new Error('Invalid JSON Pointer');
  const keys = path
    .slice(1)
    .split('/')
    .map((key) => key.replace(/~1/g, '/').replace(/~0/g, '~'));
  if (keys.length > 64 || keys.some((key) => ['__proto__', 'prototype', 'constructor'].includes(key))) {
    throw new Error('Unsafe JSON Pointer');
  }
  return keys;
}

function own(value: unknown, key: string): unknown {
  return value !== null && typeof value === 'object' && Object.hasOwn(value, key)
    ? (value as Record<string, unknown>)[key]
    : undefined;
}

export function getPointer(model: unknown, path: string): unknown {
  return segments(path).reduce<unknown>(own, model);
}

/** Copy every ancestor; never mutate the model supplied by a consumer. */
export function setPointer(model: unknown, path: string, value: unknown): unknown {
  const keys = segments(path);
  function write(current: unknown, index: number): unknown {
    if (index === keys.length) return value;
    const key = keys[index]!;
    if (Array.isArray(current)) {
      if (!/^(0|[1-9]\d*)$/.test(key) || Number(key) > current.length) throw new Error('Invalid array index');
      const copy: unknown[] = [...current];
      copy[Number(key)] = write(own(current, key), index + 1);
      return copy;
    }
    const copy: Record<string, unknown> = current && typeof current === 'object' ? { ...current } : {};
    copy[key] = write(own(current, key), index + 1);
    return copy;
  }
  return write(model, 0);
}

/** Supported command envelope. No v0.8 adaptation is performed. */
export const A2UI_VERSION = 'v0.9' as const;
export interface AgentComponent {
  id: string;
  component: string;
  children?: string[];
  /** Catalog properties are flat, alongside id/component/children. */
  [property: string]: unknown;
}
export interface AgentAction {
  name: string;
  surfaceId: string;
  context: Record<string, unknown>;
}
export interface AgentSurfaceError {
  code: 'version' | 'message' | 'component' | 'props' | 'graph' | 'binding';
  surfaceId: string;
  componentId?: string;
  type?: string;
}
type Envelope<T> = { version: typeof A2UI_VERSION } & T;
export type A2uiMessage =
  | Envelope<{ createSurface: { surfaceId: string; catalogId?: string } }>
  | Envelope<{ updateComponents: { surfaceId: string; components: AgentComponent[] } }>
  | Envelope<{ updateDataModel: { surfaceId: string; path?: string; value: unknown } }>
  | Envelope<{ deleteSurface: { surfaceId: string } }>;

export const MAX_COMPONENTS = 256;
export const MAX_DEPTH = 32;
const commands = ['createSurface', 'updateComponents', 'updateDataModel', 'deleteSurface'] as const;
const identifier = (value: unknown): value is string =>
  typeof value === 'string' && value.length > 0 && value.length <= 128;
const record = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value);

/** JSON-only, bounded input. In particular, reject cyclic JS objects and prototype keys. */
function validJson(value: unknown): boolean {
  let budget = 10000;
  const ancestors = new Set<object>();
  function visit(item: unknown, depth: number): boolean {
    if (--budget < 0 || depth > 64) return false;
    if (item === null || typeof item === 'boolean') return true;
    if (typeof item === 'number') return Number.isFinite(item);
    if (typeof item === 'string') return item.length <= 65536;
    if (typeof item !== 'object' || ancestors.has(item)) return false;
    if (!Array.isArray(item) && ![Object.prototype, null].includes(Object.getPrototypeOf(item))) return false;
    ancestors.add(item);
    const valid = Object.entries(item).every(
      ([key, child]) => !['__proto__', 'prototype', 'constructor'].includes(key) && visit(child, depth + 1),
    );
    ancestors.delete(item);
    return valid;
  }
  return visit(value, 0);
}

export function parseMessage(input: unknown): { message: A2uiMessage } | { error: AgentSurfaceError } {
  const source = record(input) ? input : {};
  const declared = commands.filter((key) => Object.hasOwn(source, key));
  const command = declared[0];
  const payload = command && record(source[command]) ? source[command] : {};
  const surfaceId = identifier(payload.surfaceId) ? payload.surfaceId : '';
  const error = (code: AgentSurfaceError['code']) => ({ error: { code, surfaceId } });
  if (source.version !== A2UI_VERSION) return error('version');
  if (declared.length !== 1 || !surfaceId || !validJson(input)) return error('message');
  if (command === 'createSurface') {
    if (payload.catalogId !== undefined && !identifier(payload.catalogId)) return error('message');
    return {
      message: {
        version: A2UI_VERSION,
        createSurface: {
          surfaceId,
          ...(typeof payload.catalogId === 'string' ? { catalogId: payload.catalogId } : {}),
        },
      },
    };
  }
  if (command === 'deleteSurface') return { message: { version: A2UI_VERSION, deleteSurface: { surfaceId } } };
  if (command === 'updateDataModel') {
    if (!Object.hasOwn(payload, 'value') || (payload.path !== undefined && typeof payload.path !== 'string'))
      return error('message');
    return {
      message: {
        version: A2UI_VERSION,
        updateDataModel: {
          surfaceId,
          path: typeof payload.path === 'string' ? payload.path : '',
          value: payload.value,
        },
      },
    };
  }
  if (!Array.isArray(payload.components) || payload.components.length > MAX_COMPONENTS) return error('message');
  const nodes: AgentComponent[] = [];
  const ids = new Set<string>();
  for (const node of payload.components) {
    if (!record(node) || !identifier(node.id) || !identifier(node.component) || ids.has(node.id))
      return error('message');
    if (
      node.children !== undefined &&
      (!Array.isArray(node.children) || node.children.length > MAX_COMPONENTS || !node.children.every(identifier))
    )
      return error('message');
    ids.add(node.id);
    nodes.push(node as AgentComponent);
  }
  return { message: { version: A2UI_VERSION, updateComponents: { surfaceId, components: nodes } } };
}

/** Missing children are allowed while streaming; repeated parents, cycles and deep trees are not. */
export function validGraph(nodes: ReadonlyMap<string, AgentComponent>): boolean {
  if (nodes.size > MAX_COMPONENTS) return false;
  const parents = new Set<string>();
  for (const node of nodes.values()) {
    for (const child of node.children ?? []) {
      if (parents.has(child)) return false;
      parents.add(child);
    }
  }
  const visiting = new Set<string>();
  function visit(id: string, depth: number): boolean {
    if (depth > MAX_DEPTH || visiting.has(id)) return false;
    visiting.add(id);
    const valid = (nodes.get(id)?.children ?? []).every((child) => visit(child, depth + 1));
    visiting.delete(id);
    return valid;
  }
  return [...nodes.keys()].every((id) => visit(id, 0));
}

import { setPointer } from './pointer';
import { parseMessage, validGraph, type A2uiMessage, type AgentComponent, type AgentSurfaceError } from './protocol';

export interface SurfaceState {
  nodes: Map<string, AgentComponent>;
  model: unknown;
  invalid?: boolean;
}
export interface StreamState {
  messages: A2uiMessage[];
  surfaces: Map<string, SurfaceState>;
  deleted: boolean;
  blocked: Set<string>;
  errors: AgentSurfaceError[];
}
export const emptyStream = (): StreamState => ({
  messages: [],
  deleted: false,
  surfaces: new Map(),
  blocked: new Set(),
  errors: [],
});

export function consume(previous: StreamState, messages: A2uiMessage[]): StreamState {
  const append = previous.messages.every((message, index) => messages[index] === message);
  const base = append ? previous : emptyStream();
  const state = {
    messages,
    deleted: base.deleted,
    surfaces: new Map(base.surfaces),
    blocked: new Set(base.blocked),
    errors: [...base.errors],
  };
  for (const input of messages.slice(base.messages.length)) {
    const parsed = parseMessage(input);
    if ('error' in parsed) {
      if (parsed.error.code === 'version') {
        state.blocked.add(parsed.error.surfaceId);
        state.surfaces.delete(parsed.error.surfaceId);
      }
      state.errors.push(parsed.error);
      continue;
    }
    const message = parsed.message;
    const payload =
      'createSurface' in message
        ? message.createSurface
        : 'updateComponents' in message
          ? message.updateComponents
          : 'updateDataModel' in message
            ? message.updateDataModel
            : message.deleteSurface;
    const { surfaceId } = payload;
    if (state.blocked.has(surfaceId)) continue;
    if ('createSurface' in message) {
      if (!state.surfaces.has(surfaceId)) {
        if (state.surfaces.size >= 32) state.errors.push({ code: 'message', surfaceId });
        else state.surfaces.set(surfaceId, { nodes: new Map(), model: {} });
      }
      continue;
    }
    const surface = state.surfaces.get(surfaceId);
    if (!surface) {
      state.errors.push({ code: 'message', surfaceId });
      continue;
    }
    if ('updateComponents' in message) {
      const nodes = new Map(surface.nodes);
      for (const node of message.updateComponents.components) {
        const old = nodes.get(node.id);
        nodes.set(node.id, { ...(old?.component === node.component ? old : {}), ...node });
      }
      const invalid = !validGraph(nodes);
      if (invalid) state.errors.push({ code: 'graph', surfaceId });
      state.surfaces.set(surfaceId, { ...surface, nodes: invalid ? surface.nodes : nodes, invalid });
    }
    if ('updateDataModel' in message) {
      try {
        const { path = '', value } = message.updateDataModel;
        state.surfaces.set(surfaceId, { ...surface, model: setPointer(surface.model, path, value) });
      } catch {
        state.errors.push({ code: 'binding', surfaceId });
      }
    }
    if ('deleteSurface' in message) {
      state.surfaces.delete(surfaceId);
      state.deleted = true;
    }
  }
  // An unsupported version suppresses all rendering and other diagnostics for that surface.
  state.errors = state.errors.filter((error) => !state.blocked.has(error.surfaceId) || error.code === 'version');
  return state;
}
